322	
323	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
324	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
325	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
326	     * steward, and when it is dated in a closed period. */
327	    @Transactional
328	    public Claim resettle(String sheetId, String user, long claimId) {
329	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
330	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
331	        refuseClosed(sheetId, claim.getDate());
332	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
333	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
334	                .orElseThrow(PersonNotFoundException::new);
335	        RollupService.Snapshot before = rollup.snapshot(sheetId);
336	        BigDecimal old = claim.getSettledDue();
337	        BigDecimal due = rollup.openShownOf(claim, person);
338	        claim.setSettledDue(due);
339	        claims.flush();
340	        log(user, person, claim);
341	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
342	        notifyWatchers(user, person, claim);
343	        rollup.recordSince(sheetId, user, before);
344	        return claim;
345	    }
346	
347	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
348	     * 7 days after the date its status log first shows it SETTLED. */
349	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
350	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
351	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
352	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
353	                .map(ClaimLog::getDate)
354	                .findFirst()
355	                .orElseThrow(ClaimStatusChangeException::new);
356	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
357	    }
358	
359	    /** The PENDING claim, locked, for a steward to approve or reject. */
360	    private Claim lockPending(String sheetId, String user, long claimId) {
361	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
362	        refuseClosed(sheetId, claim.getDate());
363	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
364	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
365	        return claim;
366	    }
367	
368	    private static String dueText(BigDecimal due) {
369	        return due == null ? "n/a" : due.toPlainString();
370	    }
371	
372	    /** The figure the claim shows and totals now, without its late charge or floor; null when it has no figure
373	     * (see {@link RollupService#figureOf}). */
374	    public BigDecimal figureOf(Claim claim, Person person) {
375	        return rollup.figureOf(claim, person);
376	    }
377	
378	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
379	     * no figure (see {@link RollupService#shownOf}). */
380	    public BigDecimal shownOf(Claim claim, Person person) {
381	        return rollup.shownOf(claim, person);
382	    }
383	
384	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
385	     * it shows now. */
386	    private void log(String user, Person person, Claim claim) {
387	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
388	                rollup.shownOf(claim, person)));
389	    }
390	
391	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
392	     * then any {@code extra} fields. */
393	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
394	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
395	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
396	                "date=" + claim.getDate()));
397	        if (number != null) fields.add("number=" + number);
398	        fields.addAll(List.of(extra));
399	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
400	    }
401	
402	    /** Notify each user watching the person, in the order they started watching, that the claim was
403	     * settled, approved or re-settled. */
404	    private void notifyWatchers(String user, Person person, Claim claim) {
405	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
406	            audit.change("NOTIFY", claim.getSheetId(), user, "user=" + watch.getUser(), "person=" + person.getName(),
407	                    "number=" + claim.getNumber());
408	        }
409	    }
410	
411	    /** The number a claim dated {@code date} is given when opened now: within the period containing
412	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
413	     * period, otherwise the next sheet-wide number. */
414	    private String nextNumber(String sheetId, LocalDate date) {
415	        if (!sheets.numbersByPeriod(sheetId)) return String.valueOf(sheets.nextClaimNumber(sheetId));
416	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
417	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
418	                .findFirst()
419	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
420	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
421	    }
422	
423	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
424	     * the user is a clerk and the due is above the sheet's clerk limit. */
425	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
426	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
427	        BigDecimal limit = settings.clerkLimit(sheetId);
428	        return limit != null && due.compareTo(limit) > 0;
429	    }
430	
431	    /** Refuse a settle or approval of the claim, whose due is {@code due}, while it has no proofs and that
432	     * due is above the proof threshold in force on its date (a due that is n/a is within any threshold). */
433	    private void refuseUnproved(Claim claim, BigDecimal due) {
434	        if (due == null || claim.getProofs() > 0) return;
435	        BigDecimal threshold = settings.proofThresholdOn(claim.getSheetId(), claim.getDate());
436	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
437	    }
438	
439	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
440	     * the person, and a claim that names one without being a correction. */
441	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
442	        if (amount.signum() >= 0) {
443	            if (corrects != null) throw new ClaimCorrectionException();
444	            return;
445	        }
446	        if (corrects == null) throw new ClaimCorrectionException();
447	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
448	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
449	                .orElseThrow(ClaimCorrectionException::new);
450	    }
451	
452	    /** Refuse a change that touches {@code date} when a closed period of the sheet contains it. */
453	    private void refuseClosed(String sheetId, LocalDate date) {
454	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
455	    }
456	
457	    private static String noteOf(String note) {
458	        return note == null ? "" : note.trim();
459	    }
460	
461	    /** The terms a claim of the person dated {@code date} is due by: the person's own terms, else those
462	     * of their grade in force on that date, else the sheet's then. */
463	    private int termsOf(String sheetId, Person person, LocalDate date) {
464	        return person.getTerms() != null ? person.getTerms() : settings.termsFor(sheetId, person.gradeOn(date), date);
465	    }
466	}
